from pathlib import Path
p=Path('src/views/CentroSoporte.vue')
s=p.read_text(encoding='utf-8')
s=s.replace("<section v-if=\"tab==='tickets'\" class=\"support-ticket-grid\">",'''<section v-if="tab==='tickets'" class="support-desk-toolbar"><div><h2>{{teamAccess?'Mesa de atención':'Mis solicitudes de soporte'}}</h2><p>{{teamAccess?'Cada solicitud tiene un responsable. Acepta un caso de la bandeja y acompaña al cliente hasta confirmar su solución.':'Aquí puedes ver quién te atiende, responder y confirmar la solución.'}}</p></div><div class="support-inbox-tabs" v-if="teamAccess"><button :class="{selected:inbox==='queue'}" @click="setInbox('queue')">Por aceptar</button><button :class="{selected:inbox==='mine'}" @click="setInbox('mine')">Mis atenciones</button><button :class="{selected:inbox===''}" @click="setInbox('')">{{supervises?'Equipo completo':'Mis casos y disponibles'}}</button></div><div class="support-actions"><button @click="board=!board">{{board?'Ver lista':'Ver tablero'}}</button><span class="support-live">Actualiza cada 20 s</span></div></section>
 <section v-if="tab==='tickets' && board" class="support-workboard"><article v-for="lane in lanes" :key="lane.key" class="support-worklane" :class="'lane-'+lane.key"><header><h3>{{lane.title}}</h3><span>{{laneTickets(lane).length}}</span></header><p class="support-lane-hint">{{lane.hint}}</p><button v-for="t in laneTickets(lane)" :key="t.id" class="support-ticket" @click="openTicket(t.id)"><div class="support-card-top"><strong>{{t.code}}</strong><span :class="'priority-'+t.priority">{{priorities[t.priority]}}</span></div><h2>{{t.subject}}</h2><p class="support-ticket-requester">{{t.requester_name || 'Cliente'}} · {{t.affected_module}}</p><div class="support-owner" :class="{'is-unassigned':!t.technician_id}"><span class="support-avatar">{{(t.assigned_name || '?').slice(0,1).toUpperCase()}}</span><span>{{t.assigned_name || 'Pendiente de aceptar'}}</span></div><footer>{{date(t.created_at)}} · {{statuses[t.status]}}</footer><span class="support-card-cta">{{!t.technician_id && teamAccess?'Abrir y aceptar atención':'Ver conversación y avances'}} →</span></button><p v-if="!laneTickets(lane).length" class="support-lane-empty">Sin casos en esta etapa</p></article></section>
 <section v-if="tab==='tickets' && !board" class="support-ticket-grid">''')
s=s.replace('<footer>{{t.origin_https}}<br>{{date(t.created_at)}}</footer>', '<div class="support-owner">Responsable: {{t.assigned_name || \'Pendiente de aceptar\'}}</div><footer>{{t.origin_https}}<br>{{date(t.created_at)}}</footer>')
s=s.replace("<p>Solicitante: {{detail.ticket.requester_name || detail.ticket.requester_id}} ? T?cnico: {{detail.ticket.assigned_name || 'Sin asignar'}}</p>",'''<section class="support-attention-banner"><span class="support-avatar">{{(detail.ticket.assigned_name || '?').slice(0,1).toUpperCase()}}</span><div><small>{{detail.ticket.technician_id?'RESPONSABLE DE TU ATENCIÓN':'SOLICITUD RECIBIDA'}}</small><strong>{{detail.ticket.assigned_name || 'Buscando un técnico disponible'}}</strong><p>{{attentionHint}}</p></div><button v-if="staff && !detail.ticket.technician_id" class="support-primary" :disabled="saving" @click="accept">Aceptar y atender ticket</button></section><p>Solicitante: {{detail.ticket.requester_name || detail.ticket.requester_id}}</p><div v-if="!staff && detail.ticket.status==='resolved'" class="support-client-confirm"><strong>Tu solución está lista. ¿Ya funciona correctamente?</strong><p>{{detail.ticket.resolution}}</p><button :disabled="saving" @click="clientDecision('closed')">Sí, confirmar solución</button><button :disabled="saving" @click="clientDecision('reopened')">Necesito más ayuda</button></div>''')
s=s.replace('<button v-if="detail.role===\'technician\' &amp;&amp; !detail.ticket.technician_id" :disabled="saving" @click="accept">Aceptar y atender ticket</button>', '')
s=s.replace('<form v-if="transitions.length"', '<form v-if="canManage && transitions.length"')
s=s.replace('<form class="support-form" @submit.prevent="send">', '<p v-if="staff && !canManage" class="support-ownership-note">Acepta la solicitud para responder al cliente. Cada atención debe tener un responsable.</p><form v-if="!staff || canManage" class="support-form" @submit.prevent="send">')
s=s.replace('<details v-if="staff"><summary>Tiempo', '<details v-if="canManage"><summary>Tiempo')
s=s.replace("{{r.technician_id?'Técnico #'+r.technician_id:'Sin asignar'}}", "{{r.technician_name || (r.technician_id?'Técnico #'+r.technician_id:'Sin asignar')}}")
s=s.replace('<th>Resueltos / cerrados</th>', '<th>Resueltos / cerrados</th><th>Respuesta</th><th>Solución</th><th>Calificación</th>')
s=s.replace('<td>{{r.resolved}}</td>', '<td>{{r.resolved}}</td><td>{{minutes(r.response_minutes)}}</td><td>{{minutes(r.resolution_minutes)}}</td><td>{{r.rating_count?Number(r.rating).toFixed(1)+\' / 5 · \'+r.rating_count+\' opiniones\':\'Sin calificaciones\'}}</td>')
s=s.replace("tab:'tickets',statuses", "tab:'tickets',inbox:'',board:true,lanes:[{key:'queue',title:'Por aceptar',hint:'Solicitudes que necesitan responsable',states:['new','assigned','reopened']},{key:'working',title:'En atención',hint:'El técnico trabaja en la solución',states:['in_progress']},{key:'waiting',title:'En seguimiento',hint:'Esperando al cliente o apoyo técnico',states:['waiting_customer','escalated']},{key:'done',title:'Solución y confirmación',hint:'El cliente confirma y califica',states:['resolved','closed','cancelled']}],statuses")
s=s.replace('computed:{embedded()', '''computed:{teamAccess(){return !!this.context.superadmin || (this.context.roles||[]).some(r=>['technician','supervisor'].includes(r.role))},supervises(){return !!this.context.superadmin || (this.context.roles||[]).some(r=>r.role==='supervisor')},canManage(){return this.staff && (this.detail.role!=='technician' || (this.detail.ticket && Number(this.detail.ticket.technician_id)===Number(this.context.principal)))},attentionHint(){const t=this.detail.ticket;if(!t)return '';if(t.status==='resolved')return 'La solución fue registrada. El cliente puede confirmarla o pedir más ayuda.';if(t.status==='closed')return 'Atención confirmada. Gracias por ayudarnos a mejorar con tu calificación.';if(t.status==='waiting_customer')return 'Necesitamos tu respuesta para continuar. Escríbenos en la conversación.';if(t.status==='escalated')return 'El caso necesita apoyo especializado y conserva su seguimiento.';return t.technician_id?'Tu técnico te responderá en esta conversación. Las notas internas no se muestran al cliente.':'El equipo recibió tu solicitud. Aquí verás el nombre de quien la acepte.'},embedded()''')
s=s.replace("if(this.detailOpen&&!document.hidden&&!this.saving)this.refreshDetail()", "if(!document.hidden&&!this.saving){if(this.detailOpen)this.refreshDetail();else if(this.tab==='tickets')this.loadTickets()}")
s=s.replace("elapsed(start,end)", "laneTickets(lane){return this.tickets.filter(t=>lane.states.includes(t.status))},setInbox(inbox){this.inbox=inbox;this.loadTickets()},async clientDecision(status){if(await this.act('transition',{id:this.detail.ticket.id,version:this.detail.ticket.version,status,reason:status==='closed'?'Cliente confirma que la solución funciona':'Cliente solicita continuar la atención'})){await this.refreshDetail();await this.loadTickets()}},elapsed(start,end)")
s=s.replace("Object.assign({},this.filters,more?", "Object.assign({},this.filters,{inbox:this.inbox},more?")
# Keep drafts during periodic refresh; mutation controls are disabled while saving.
s=s.replace("await this.loadTickets()}},\n async get", "await this.loadTickets();this.success='Atención aceptada. El cliente ya puede ver quién lo atiende; envía tu primera respuesta.'}},\n async get")
p.write_text(s,encoding='utf-8')
